document.addEventListener('DOMContentLoaded', function () {
// First script - Nav menu
const menuTrigger = document.querySelector('.nav_menu-trigger-wrap');
const navLinks = document.querySelector('.nav_actions');
menuTrigger.addEventListener('click', function (e) {
  e.stopPropagation();
  // Close sidebar if it's open
  if (isMobile() && sidebar.classList.contains('active')) {
    toggleSidebar();
  }
  if (navLinks.getAttribute('data-active') === 'true') {
    navLinks.removeAttribute('data-active');
    menuTrigger.removeAttribute('data-active');
  } else {
    navLinks.setAttribute('data-active', 'true');
    menuTrigger.setAttribute('data-active', 'true');
  }
});
// Second script - Mobile sidebar
const isMobile = () => {
  return (window.matchMedia('(max-width: 767px)').matches ||
    (window.matchMedia('(max-height: 767px) and (orientation: landscape)').matches));
};
// Declare sidebar and its functions at the top level so they're accessible to nav trigger
let sidebar, toggleSidebar;
if (isMobile()) {
  sidebar = document.querySelector('.documentation-sidebar-fixed');
  const indicator = document.querySelector('.indicator');
  const overlayBg = document.querySelector('.overlay-bg');
  const xIcon = document.querySelector('.x-svg');
  const headingIcon = document.querySelector('.heading-svg');
  const sidebarLinks = document.querySelectorAll('.sidebar-link');
  xIcon.style.display = 'none';
  headingIcon.style.display = 'block';
  const toggleIcons = (isActive) => {
    xIcon.style.display = isActive ? 'block' : 'none';
    headingIcon.style.display = isActive ? 'none' : 'block';
  };
  toggleSidebar = () => {
    const isActive = !sidebar.classList.contains('active');
    sidebar.classList.toggle('active');
    overlayBg.classList.toggle('active');
    document.body.classList.toggle('no-scroll');
    toggleIcons(isActive);
  };
  indicator.addEventListener('click', () => {
    toggleSidebar();
  });
  sidebarLinks.forEach(link => {
    link.addEventListener('click', () => {
      toggleSidebar();
    });
  });
  // Combined click outside handler
  document.addEventListener('click', function (e) {
    // Handle nav menu
    if (!navLinks.contains(e.target)) {
      navLinks.removeAttribute('data-active');
      menuTrigger.removeAttribute('data-active');
    }
    // Handle sidebar
    const isClickInside = sidebar.contains(e.target) || indicator.contains(e.target);
    if (sidebar.classList.contains('active') && !isClickInside && !menuTrigger.contains(e.target)) {
      toggleSidebar();
    }
  });
  // Prevent clicks inside sidebar from closing it
  sidebar.addEventListener('click', (e) => {
    e.stopPropagation();
  });
} else {
  // Handle nav menu click outside for non-mobile devices
  document.addEventListener('click', function (e) {
    if (!navLinks.contains(e.target)) {
      navLinks.removeAttribute('data-active');
      menuTrigger.removeAttribute('data-active');
    }
  });
}
});
